1	package store
2	
3	import (
4		"errors"
5		"sync"
6	)
7	
8	// crdtSubKey identifies the set of CRDT state subscriptions belonging to one
9	// device's view of one document: a state-changing commit fans out to every
10	// device set under the document, a permission revoke closes only the one
11	// (document, device) set.
12	type crdtSubKey struct {
13		document string
14		device   string
15	}
16	
17	// CRDTSubscription is one in-memory, push-only subscription to a document's
18	// merged CRDT state. States that actually changed the merge are appended in
19	// transaction-commit order and handed to the connection in that order; the
20	// wake channel is merely a coalescing "drain the queue" signal. A permission
21	// revoke targeting the subscription's (document, device) pair is delivered as
22	// a separate, one-shot closed channel so it can neither be missed nor undone
23	// by a later grant on the same connection.
24	//
25	// Like change-log subscriptions, a CRDT subscription leaves no durable trace:
26	// nothing is written to the database, a disconnect simply unregisters, and
27	// closing the store wakes every subscription once (the server maps that to a
28	// going-away close). Pushing never writes an operation and never moves the
29	// merge; the subscription layer only observes committed states.
30	type CRDTSubscription struct {
31		// mu guards queue.
32		mu sync.Mutex
33		// queue holds merged states in commit order that the connection has not
34		// drained yet. It is unbounded: every committed state change must reach
35		// the subscriber exactly once and in order, so a slow consumer is never
36		// allowed to drop or coalesce a state.
37		queue []CRDTState
38		// wakes is a 1-buffered "drain now" signal; repeated notifications while
39		// one is pending coalesce because Drain always empties the whole queue.
40		wakes chan struct{}
41		// revoked is closed once, the first time permission for the keyed pair is
42		// revoked while this subscription is live. Closing is sticky: a later
43		// grant never reopens it.
44		revoked       chan struct{}
45		revokedClosed bool
46	}
47	
48	// Wake returns the coalescing drain signal.
49	func (x *CRDTSubscription) Wake() <-chan struct{} { return x.wakes }
50	
51	// Revoked returns the one-shot revoke signal.
52	func (x *CRDTSubscription) Revoked() <-chan struct{} { return x.revoked }
53	
54	// Drain removes and returns every queued merged state in commit order. It
55	// returns nil when the queue is empty.
56	func (x *CRDTSubscription) Drain() []CRDTState {
57		x.mu.Lock()
58		defer x.mu.Unlock()
59		if len(x.queue) == 0 {
60			return nil
61		}
62		out := x.queue
63		x.queue = nil
64		return out
65	}
66	
67	// deliver appends a committed merged state and pokes the drain signal. It is
68	// non-blocking: a wake already pending covers this state because the consumer
69	// drains the whole queue each time it runs.
70	func (x *CRDTSubscription) deliver(state CRDTState) {
71		x.mu.Lock()
72		x.queue = append(x.queue, state)
73		x.mu.Unlock()
74		select {
75		case x.wakes <- struct{}{}:
76		default:
77		}
78	}
79	
80	// AddCRDTSubscription registers an in-memory subscription to documentID as
81	// seen by deviceID and returns it together with an idempotent unregister that
82	// a client disconnect, a permission close and a store close may all race to
83	// call.
84	//
85	// Registration precedes the subscriber's first state read, so a state-changing
86	// commit landing between registration and that read is queued and cannot be
87	// missed; the subscriber compares a queued state with the one it last sent and
88	// skips an identical one, which makes register-then-read ordering harmless.
89	//
90	// If the store is already closing the subscription's wake is signaled
91	// immediately and unregister is a no-op, so a late subscriber ends at once
92	// with the going-away close instead of parking forever.
93	func (s *Store) AddCRDTSubscription(documentID, deviceID string) (*CRDTSubscription, func()) {
94		sub := &CRDTSubscription{
95			wakes:   make(chan struct{}, 1),
96			revoked: make(chan struct{}),
97		}
98		key := crdtSubKey{document: documentID, device: deviceID}
99	
100		s.pollMu.Lock()
101		defer s.pollMu.Unlock()
102		if s.closed {
103			close(sub.wakes)
104			return sub, func() {}
105		}
106		s.subWG.Add(1)
107		if s.crdtSubs == nil {
108			s.crdtSubs = make(map[crdtSubKey]map[uint64]*CRDTSubscription)
109		}
110		s.nextCRDTSubID++
111		id := s.nextCRDTSubID
112		set := s.crdtSubs[key]
113		if set == nil {
114			set = make(map[uint64]*CRDTSubscription)
115			s.crdtSubs[key] = set
116		}
117		set[id] = sub
118		unregister := func() {
119			s.pollMu.Lock()
120			if set, ok := s.crdtSubs[key]; ok {
121				if _, ok := set[id]; ok {
122					delete(set, id)
123					if len(set) == 0 {
124						delete(s.crdtSubs, key)
125					}
126					s.pollMu.Unlock()
127					s.subWG.Done()
128					return
129				}
130			}
131			s.pollMu.Unlock()
132		}
133		return sub, unregister
134	}
135	
136	// OpenCRDTSubscription atomically registers a CRDT state subscription and
137	// reads the document's current merged state. It returns:
138	//
139	//   - state: the current merged state, or nil when no CRDT operation has ever
140	//     been committed for the document (the subscriber then waits silently);
141	//   - sub: the live subscription;
142	//   - unregister: idempotent removal.
143	//
144	// Registration and the read happen as one step relative to a SubmitCRDTOps
145	// commit — both hold crdtMu — so a state-changing commit lands either inside
146	// the returned initial state or in the subscription's queue, never in both and
147	// never neither; the subscriber therefore never misses the first state and
148	// never sends a queued state that is older than its initial one. When the
149	// store is already closing the wake is signaled immediately and unregister is
150	// a no-op, so the connection ends with a going-away close instead of parking.
151	func (s *Store) OpenCRDTSubscription(documentID, deviceID string) (state *CRDTState, sub *CRDTSubscription, unregister func(), err error) {
152		s.crdtMu.Lock()
153		defer s.crdtMu.Unlock()
154	
155		sub, unregister = s.AddCRDTSubscription(documentID, deviceID)
156		current, getErr := s.GetCRDTState(documentID)
157		switch {
158		case errors.Is(getErr, ErrCRDTNotFound):
159			return nil, sub, unregister, nil
160		case getErr != nil:
161			unregister()
162			return nil, nil, func() {}, getErr
163		}
164		return &current, sub, unregister, nil
165	}
166	
167	// notifyCRDTSubscribers publishes a newly merged state to every CRDT
168	// subscription open on documentID. It is called only after a state-changing
169	// CRDT transaction has committed, so every pushed state is durable and states
170	// arrive in transaction-commit order. Idempotent repeats, rejected batches and
171	// no-op additions never call it, so such commits push nothing.
172	func (s *Store) notifyCRDTSubscribers(documentID string, state CRDTState) {
173		s.pollMu.Lock()
174		var targets []*CRDTSubscription
175		for key, set := range s.crdtSubs {
176			if key.document != documentID {
177				continue
178			}
179			for _, sub := range set {
180				targets = append(targets, sub)
181			}
182		}
183		s.pollMu.Unlock()
184	
185		for _, sub := range targets {
186			sub.deliver(state)
187		}
